// The LaunchBox wallpaper picked for a title, or NULL - see
// tools/data/launchbox-backgrounds.txt.
static const char *LaunchBoxBackgroundFile(unsigned long titleId)
{
    int lo = 0, hi = (int)(sizeof(kLaunchBoxBackgrounds) / sizeof(kLaunchBoxBackgrounds[0])) - 1;
    while (lo <= hi)
    {
        const int mid = (lo + hi) / 2;
        if (kLaunchBoxBackgrounds[mid].titleId == titleId)
            return kLaunchBoxBackgrounds[mid].file;
        if (kLaunchBoxBackgrounds[mid].titleId < titleId)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return NULL;
}

bool HasLaunchBoxBackground(unsigned long titleId)
{
    return LaunchBoxBackgroundFile(titleId) != NULL;
}

// Screenshot n (1 up) of an Original Xbox game, by title ID, or an indie
// game, by its IndieGameKey - from LaunchBox, as Xbox Live has none of
// either (XboxInfo.h, IndieInfo.h). False if there's no such one.
static bool LaunchBoxScreenshotFile(unsigned long key, int n, char *out, size_t outSize)
{
    const char *list = NULL;
    if (IsIndieGameKey(key))
    {
        const IndieInfo *info = IndieInfoOf(key);
        list = info != NULL ? info->screenshots : NULL;
    }
    else
    {
        const XboxInfo *info = XboxInfoOf(key);
        list = info != NULL ? info->screenshots : NULL;
    }
    for (int i = 1; list != NULL && *list != '\0'; ++i)
    {
        const char *end = strchr(list, ' ');
        const size_t len = end != NULL ? (size_t)(end - list) : strlen(list);
        if (i == n)
        {
            if (len >= outSize)
                return false;
            memcpy(out, list, len);
            out[len] = '\0';
            return true;
        }
        list = end != NULL ? end + 1 : list + len;
    }
    return false;
}

// A LaunchBox image - a wallpaper or a screenshot - over HTTPS, kept at
// path as the marketplace's would be, so it's asked for once. NULL if it
// can't be had now; it is asked again next time, as a failure here says
// nothing about LaunchBox.
static unsigned char *FetchLaunchBoxBackground(unsigned long titleId, const char *file, const char *path,
                                               unsigned long *outSize)
{
    char url[160];
    _snprintf(url, sizeof(url), LAUNCHBOX_URL, file);
    url[sizeof(url) - 1] = '\0';

    char *image = (char *)malloc(IMAGE_MAX_BYTES + 1);
    if (image == NULL)
        return NULL;
    unsigned long long len = IMAGE_MAX_BYTES;
    const int status = httpRequestHTTPS(url, HTTP_GET, NULL, NULL, "", image, &len, false, NULL, 0, QuietPrint);
    dprintf("[store] %08lX: LaunchBox %s -> HTTP %d, %I64u bytes\n", titleId, file, status, len);
    if (status != 200 || len < 64)
    {
        free(image);
        return NULL;
    }
    if (!WriteWholeFile(path, (unsigned char *)image, (unsigned long)len))
        dprintf("[store] couldn't write %s\n", path);
    *outSize = (unsigned long)len;
    return (unsigned char *)image;
}

// From the cache, else the marketplace, else LaunchBox for a wallpaper.
// NULL if there's nothing to show.
static unsigned char *LoadArt(unsigned long titleId, StoreArtKind kind, unsigned long *outSize)
{
    char path[64], marker[64], file[32];
    CachePath(titleId, kind, "jpg", path, sizeof(path));
    CachePath(titleId, kind, "none", marker, sizeof(marker));
    FileNameOf(kind, file, sizeof(file));

    unsigned char *bytes = ReadWholeFile(path, IMAGE_MAX_BYTES, outSize);
    if (bytes != NULL)
        return bytes;

    // A wallpaper LaunchBox has is for a game the marketplace has none for -
    // every Original Xbox game, and the 360's in the table - so it goes
    // straight there.
    const char *launchBox = (kind == STORE_ART_BACKGROUND) ? LaunchBoxBackgroundFile(titleId) : NULL;
    if (launchBox != NULL)
        return FetchLaunchBoxBackground(titleId, launchBox, path, outSize);
    // So do an Original Xbox or indie game's screenshots.
    char shot[96];
    if (kind >= STORE_ART_SCREEN && LaunchBoxScreenshotFile(titleId, kind - STORE_ART_SCREEN, shot, sizeof(shot)))
        return FetchLaunchBoxBackground(titleId, shot, path, outSize);
    // An indie game's key is no title ID: the marketplace has nothing by it.
    if (IsIndieGameKey(titleId))
        return NULL;
    if (WrittenRecently(marker))
        return NULL;

    char url[160];
    _snprintf(url, sizeof(url), IMAGE_BASE_URL, titleId, file);
    url[sizeof(url) - 1] = '\0';

    char *image = (char *)malloc(IMAGE_MAX_BYTES + 1);
    if (image == NULL)
        return NULL;

    unsigned long long len = 0;
    int status = HttpGetPlain(url, NULL, image, IMAGE_MAX_BYTES, &len);
    if (status != 200 || len < 64)
    {
        dprintf("[store] %08lX %s: HTTP %d, %I64u bytes\n", titleId, file, status, len);
        free(image);
        // The marketplace answering is the only sign it has nothing; a
        // network failure is tried again next time.
        if (status == 404 || status == 403)
            WriteWholeFile(marker, NULL, 0);
        return NULL;
    }

    if (!WriteWholeFile(path, (unsigned char *)image, (unsigned long)len))
        dprintf("[store] couldn't write %s\n", path);
    DeleteFileA(marker);

    *outSize = (unsigned long)len;
    return (unsigned char *)image;
}

